import{_ as t,a0 as l,w as o,s as d,I as a,x as n,a1 as i,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"用 AWK 喝咖啡 | LCTT x X-CMD","titleTemplate":false,"description":"用 AWK 喝咖啡 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 AWK 喝咖啡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 AWK 喝咖啡 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190214 Drinking coffee with AWK","title":"用 AWK 喝咖啡","tag":"201902","desc":""},"relativePath":"201902/20190214 Drinking coffee with AWK.md","filePath":"[post].md"}'),g={name:"201902/20190214 Drinking coffee with AWK.md"};function u(h,s,k,b,m,c){const e=l("Link");return o(),d("div",null,[s[18]||(s[18]=a("h1",{id:"用-awk-喝咖啡",tabindex:"-1"},[n("用 AWK 喝咖啡 "),a("a",{class:"header-anchor",href:"#用-awk-喝咖啡","aria-label":"Permalink to “用 AWK 喝咖啡”"},"​")],-1)),s[19]||(s[19]=a("blockquote",null,[a("p",null,"用一个简单的 AWK 程序跟踪你的同事喝咖啡的欠款。")],-1)),s[20]||(s[20]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/coffee_cafe_brew_laptop_desktop.jpg?itok=G-n1o1-o",alt:""})],-1)),s[21]||(s[21]=a("p",null,"以下基于一个真实的故事，虽然一些名字和细节有所改变。",-1)),s[22]||(s[22]=a("blockquote",null,[a("p",null,[n("很久以前，在一个遥远的地方，有一间"),a("s",null,"庙"),n("（划掉）办公室。由于各种原因，这个办公室没有购买速溶咖啡。所以那个办公室的一些人聚在一起决定建立“咖啡角”。")]),a("p",null,"咖啡角的一名成员会购买一些速溶咖啡，而其他成员会付给他钱。有人喝咖啡比其他人多，所以增加了“半成员”的级别：半成员每周允许喝的咖啡限量，并可以支付其它成员支付的一半。")],-1)),a("p",null,[s[1]||(s[1]=n("管理这事非常操心。而我刚读过《Unix 编程环境》这本书，想练习一下我的 ",-1)),i(e,{href:"https://en.wikipedia.org/wiki/AWK"},{default:p(()=>[...s[0]||(s[0]=[n("AWK",-1)])]),_:1}),s[2]||(s[2]=n(" 编程技能，所以我自告奋勇创建了一个系统。",-1))]),s[23]||(s[23]=r(`<p>第 1 步：我用一个数据库来记录成员及其应支付给咖啡角的欠款。我是以 AWK 便于处理的格式记录的，其中字段用冒号分隔：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>member:john:1:22</span></span>
<span class="line"><span>member:jane:0.5:33</span></span>
<span class="line"><span>member:pratyush:0.5:17</span></span>
<span class="line"><span>member:jing:1:27</span></span></code></pre></div><p>上面的第一个字段标识了这是哪一种行（<code>member</code>）。第二个字段是成员的名字（即他们的电子邮件用户名，但没有 @ ）。下一个字段是其成员级别（成员 = 1，或半会员 = 0.5）。最后一个字段是他们欠咖啡角的钱。正数表示他们欠咖啡角钱，负数表示咖啡角欠他们。</p><p>第 2 步：我记录了咖啡角的收入和支出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>payment:jane:33</span></span>
<span class="line"><span>payment:pratyush:17</span></span>
<span class="line"><span>bought:john:60</span></span>
<span class="line"><span>payback:john:50</span></span></code></pre></div><p>Jane 付款 $33，Pratyush 付款 $17，John 买了价值 $60 的咖啡，而咖啡角还款给 John $50。</p><p>第 3 步：我准备写一些代码，用来处理成员和付款，并生成记录了新欠账的更新的成员文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env --split-string=awk -F: -f</span></span></code></pre></div><p>释伴行（<code>＃!</code>）需要做一些调整，我使用 <code>env</code> 命令来允许从释伴行传递多个参数：具体来说，AWK 的 <code>-F</code> 命令行参数会告诉它字段分隔符是什么。</p><p>AWK 程序就是一个规则序列（也可以包含函数定义，但是对于这个咖啡角应用来说不需要）</p><p>第一条规则读取该成员文件。当我运行该命令时，我总是首先给它的是成员文件，然后是付款文件。它使用 AWK 关联数组来在 <code>members</code> 数组中记录成员级别，以及在 <code>debt</code> 数组中记录当前欠账。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$1 == &quot;member&quot; {</span></span>
<span class="line"><span>   members[$2]=$3</span></span>
<span class="line"><span>   debt[$2]=$4</span></span>
<span class="line"><span>   total_members += $3</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>第二条规则在记录付款（<code>payment</code>）时减少欠账。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$1 == &quot;payment&quot; {</span></span>
<span class="line"><span>   debt[$2] -= $3</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>还款（<code>payback</code>）则相反：它增加欠账。这可以优雅地支持意外地给了某人太多钱的情况。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$1 == &quot;payback&quot; {</span></span>
<span class="line"><span>   debt[$2] += $3</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>最复杂的部分出现在有人购买（<code>bought</code>）速溶咖啡供咖啡角使用时。它被视为付款（<code>payment</code>），并且该人的债务减少了适当的金额。接下来，它计算每个会员的费用。它根据成员的级别对所有成员进行迭代并增加欠款</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$1 == &quot;bought&quot; {</span></span>
<span class="line"><span>   debt[$2] -= $3</span></span>
<span class="line"><span>   per_member = $3/total_members</span></span>
<span class="line"><span>   for (x in members) {</span></span>
<span class="line"><span>       debt[x] += per_member * members[x]</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>END</code> 模式很特殊：当 AWK 没有更多的数据要处理时，它会一次性执行。此时，它会使用更新的欠款数生成新的成员文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>END {</span></span>
<span class="line"><span>   for (x in members) {</span></span>
<span class="line"><span>       printf &quot;%s:%s:%s\\n&quot;, x, members[x], debt[x]</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>再配合一个遍历成员文件，并向人们发送提醒电子邮件以支付他们的会费（积极清账）的脚本，这个系统管理咖啡角相当一段时间。</p><hr>`,22)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),i(e,{href:"https://opensource.com/article/19/2/drinking-coffee-awk"},{default:p(()=>[...s[3]||(s[3]=[n("https://opensource.com/article/19/2/drinking-coffee-awk",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=n("作者：",-1)),i(e,{href:"https://opensource.com/users/moshez"},{default:p(()=>[...s[5]||(s[5]=[n("Moshe Zadka",-1)])]),_:1}),s[10]||(s[10]=n(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 译者：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1}),s[12]||(s[12]=n(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[n("Linux中国",-1)])]),_:1}),s[17]||(s[17]=n(" 荣誉推出",-1))])])}const C=t(g,[["render",u]]);export{x as __pageData,C as default};
